import { Flex, Heading, HStack, Text } from "@chakra-ui/react";
import type { ReactNode } from "react";
import { InspectorViewPopover } from "./InspectorViewPopover";

interface Props {
  title: string;
  text?: string;
  badge?: ReactNode;
  sticky?: boolean;
  showViewSwitcher?: boolean;
}

export const InspectorViewHeader = ({
  title,
  text,
  badge,
  sticky,
  showViewSwitcher = true,
}: Props) => {
  const stickyStyles = {
    position: "absolute",
    top: "0",
    left: "0",
    right: "0",
  };
  return (
    <Flex
      height="12"
      flexShrink={0}
      px="6"
      alignItems="center"
      justifyContent="space-between"
      css={sticky ? stickyStyles : {}}
      data-testid="inspector-view-header"
    >
      <HStack minWidth={0} gap="1">
        <Heading textStyle="sm">{title}</Heading>
        {text && (
          <Text textStyle="sm" overflow="hidden" textOverflow="ellipsis" whiteSpace="nowrap">
            {text}
          </Text>
        )}
        {badge}
      </HStack>
      {showViewSwitcher && <InspectorViewPopover />}
    </Flex>
  );
};
